fn enc_producer_claim(out: &mut Vec<u8>, v: &ProducerClaim, depth: i32) {
    out.push(b'{');
    let mut first = true;
    if !v.provider.is_empty() {
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "provider");
        out.extend_from_slice(b": ");
        esc(out, &v.provider);
    }
    if !v.program.is_empty() {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "program");
        out.extend_from_slice(b": ");
        esc(out, &v.program);
    }
    if !v.exe.is_empty() {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "exe");
        out.extend_from_slice(b": ");
        esc(out, &v.exe);
    }
    if !v.user.is_empty() {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "user");
        out.extend_from_slice(b": ");
        esc(out, &v.user);
    }
    if v.pid != 0 {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "pid");
        out.extend_from_slice(b": ");
        num(out, v.pid);
    }
    if v.uid != 0 {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "uid");
        out.extend_from_slice(b": ");
        num(out, v.uid);
    }
    if v.gid != 0 {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "gid");
        out.extend_from_slice(b": ");
        num(out, v.gid);
    }
    if !first {
        out.push(b'\n');
        pad(out, depth);
    }
    out.push(b'}');
}

